def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Create a dictionary to keep track of the class hierarchy
    hierarchy = {}
    for cls in classes:
        hierarchy[cls] = set(cls.__bases__)

    # Initialize the minimal bases list with the first class
    minimal_bases = [classes[0]]

    # Loop through the remaining classes and add them to the minimal list if they are not already inherited
    for cls in classes[1:]:
        # Check if the class is already inherited by the current minimal bases
        inherited = False
        for base in minimal_bases:
            if cls in hierarchy[base]:
                inherited = True
                break

        # If the class is not inherited, add it to the minimal bases list
        if not inherited:
            minimal_bases.append(cls)

    return minimal_bases

