def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for arg in sequence:
        if isinstance(arg, Declaration):
            output.append(arg)
        elif isinstance(arg, tuple):
            output.extend(_normalizeargs(arg))
        elif isinstance(arg, Interface):
            output.append(Argument(arg))
        else:
            raise ValueError("Unknown declaration argument type: " + str(type(arg)))
    return output

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if isinstance(sequence, tuple) and len(sequence) == 2:
        sequence, output = sequence
    if not isinstance(sequence, list):
        if isinstance(sequence, (Declarion, ImplementsSpec)) or (isinstance(sequence, tuple) and len(sequence) > 1):
            output = [sequence, output or []]
        else:
            raise ValueError("Expected Declaration or tuple of Declarations or ImplSpecs")
    if not all(isinstance(decl, (Declarion, ImplSpec)) for decl in sequence):
        raise ValueError("Expected sequence of Declarations or ImplSpecs")

    seen_classes = {}

    for decl in sequence:
        if isinstance(decl, ImplSpec):
            output.append(decl)
        else:
            interfaces_to_add = []
            for interface in decl.interfaces:
                if interface in seen_classes:
                    for implspec in seen_classes[interface]:
                        output.append(implspec)
                else:
                    interfaces_to_add.append(interface)
            for interface in interfaces_to_add:
                seen_classes[interface] = ImplSpec(interface, decl.args, decl.kwargs)

    return output




