    """
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")

    if coord_name not in self.coords:
        raise ValueError("coord_name must be a valid coordinate name")

    err_indices = []
    for i, name in enumerate(self.err_names):
