def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not isinstance(coord, (list, tuple)):
        raise TypeError("Coord must be a list or a tuple")

    if not isinstance(weight, (int, float)):
        raise TypeError("Weight must be a number")

    if weight < 0:
        raise ValueError("Weight must be non-negative")

    if len(coord) != self.axes:
        raise ValueError("Length of coord must match the number of axes")

    for i, c in enumerate(coord):
        if not isinstance(c, (int, float)):
            raise TypeError("Coordinate element must be a number")
        if c < self.edges[i][0] or c >= self.edges[i][-1]:
            return

    self.bincounts[tuple(coord)] += weight

def _validate_labels(labels):
    """
    Check that the keys and values in the given labels match against their corresponding regular expressions.

    Args:
        labels (dict): the different labels to validate

    Raises:
        ValidationError: if any of the keys and labels does not match their respective regular expression. The error contains as message the list of all errors which occurred in the labels.
    """
    invalid_labels = {}
    for key, value in labels.items():
        try:
            if not isinstance(key, str):
                raise ValidationError(f"Keys in labels must be strings, got {type(key)}.")
            if not isinstance(value, str) and not isinstance(value, bytes):
                raise ValidationError(
                    f"Values in labels must be strings or bytes-like objects, got {type(value)}.")
            pattern = LABEL_REGEX[key]
            if not pattern.match(value):
                raise ValidationError(
                    f"Label value {value} does not match the regex {pattern.pattern}")
        except ValidationError as err:
            invalid_labels[key] = err.messages
    if invalid_labels:
        raise ValidationError(message=json.dumps(invalid_labels))

