def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not size:
        return 0
    size = size.upper()
    num = ''
    unit = ''
    for c in size:
        if c in '0123456789.':
            num += c
        else:
            unit += c
    if not unit:
        unit = 'B'
    if unit == 'B':
        multiplier = 1
    elif unit == 'KB':
        multiplier = 1000
    elif unit == 'KiB':
        multiplier = 1024
    elif unit == 'MB':
        multiplier = 1000 ** 2
    elif unit == 'MiB':
        multiplier = 1024 ** 2
    elif unit == 'GB':
        multiplier == 1000 ** 3
    elif unit == 'GiB':
        multiplier = 1024 ** 3
    elif unit == 'TB':
        multiplier = 1000 ** 4
    elif unit == 'TiB':
        multiplier = 1024 ** 4
    else:
        raise ValueError(f"Unknown unit {unit}")
    return int(float(num) * multiplier)

