def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    parsed_href = urllib.parse.urlparse(image_href)
    netloc = parsed_href.netloc
    try:
        image_id = urllib.parse.parse_qs(parsed_href.query)?['image_id'][0]
    except KeyError:
        raise ValueError(f"Expected image_href to contain 'image_id' query parameter: {image_href}")
    use_ssl = parsed_href.scheme == 'https'
    return (image_id, netloc, use_ssl)

