class Graph:
    def __init__(self, fields):
        self.fields = fields
        self.scale = None

    def scale(self, other=None):
        if other is None:
            return self.scale
        self._check_scale()
        self.scale = other
        for field in self.fields:
            field.scale(other)

    def _check_scale(self):
        if self.scale is None or self.scale <= 0:
            raise LenaValueError("Graph has unknown or zero scale")

