    """Convert a :class:`.histogram` to a :class:`.graph`.

    Args:
        hist (histogram): The input histogram.
        make_value (Callable, optional): A function to create the graph's point value from a histogram bin.
        get_coordinate (str, optional): The coordinate of a graph point created from a histogram bin. Defaults to "left".
        field_names (Tuple, optional): Field names of the graph. Defaults to ("x", "y").
        scale (Any, optional): The graph's scale. Defaults to None.

    Returns:
        graph: The resulting graph.
    """
    if make_value is None:
        make_value = lambda bin_: bin_.content

    if get_coordinate == "left":
        x_values = hist.bin_left_edges
    elif get_coordinate == "right":
        x_values = hist.bin_right_edges
    elif get_coordinate == "middle":
        x_values = hist.bin_middle_edges
    else:
        raise ValueError("Invalid get_coordinate")

    y_values = make_value(hist)

    if scale is True:
        scale = hist.scale

    return Graph(x_values, y_values, field_names=field_names, scale=scale)

