def find_tags(text: str, replacer: callable=None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    new_text = text

    for match in re.finditer(r"\S+", text):
        word = match.group(0)
        if word == "":
            continue

        if word[0] == "<" and word[-1] == ">":
            if word.count("<") != 1 or word.count(">") != 1:
                continue

            tags.add(word[1:-1])

            if replacer is not None:
                new_text = new_text.replace(word, replacer(word))

    return tags, new_text

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    is_code_block = False
    code_block_char = None
    replaced_text = ""
    for word in text.split():
        if word.startswith("<") and not is_code_block:
            tags.add(word[1:-1])
            if replacer:
                replaced_text += replacer(word) + " "
        elif word.startswith(">") and is_code_block and code_block_char == word[1]:
            is_code_block = False
            code_block_char = None
            replaced_text += word + " "
        elif word == "<" or word == ">" and not is_code_block:
            is_code_block = True
            code_block_char = word
            replaced_text += word + " "
        else:
            replaced_text += word + " "
    if is_code_block:
        raise ValueError(f"Mismatched code block characters in text: {text}")
    return tags, replaced_text.strip()

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    new_text = text

    for match in re.finditer(r'\B#(\w+)', text):
        tag = match.group(1)
        tags.add(tag)

        if replacer is not None:
            new_text = new_text.replace(match.group(0), replacer(tag))

    return tags, new_text

