def dict_insert(dic, val, key, *keys):
    """
    Insert a value of a nested key into a dictionary.

    To insert the value for a nested key, all ancestor keys should be given as method arguments.

    Example:
        dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: A dictionary object to insert the nested key value into.
    :param val: A value to insert into the given dictionary.
    :param key: The first key in the chain of keys that will store the value.
    :param keys: The sub keys in the keys chain.
    """
    if key not in dic:
        dic[key] = {}
    if keys:
        dic = dic[key]
        for i, subkey in enumerate(keys):
            if subkey not in dic:
                dic[subkey] = {}
            dic = dic[subkey]
        dic[val] = val
    else:
        dic[key] = val

