    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    try:
        with open(yaml_file) as file:
            data = yaml.safe_load(file.read())
    except FileNotFoundError:
        raise IRValidatorException(f'{yaml_file} does not exist.')
    except YAMLError:
        raise IRValidatorException(f'{yaml_file} is not a valid YAML file.')

    missing_fields = []
    for required_field in cls.REQUIRED_FIELDS:
        if required_field not in data:
            missing_fields.append(required_field)

    if missing_fields:
        raise IRValidatorException(f'{yaml_file} is missing required fields: {missing_fields}.')

    return data

