    """Resolve arguments' values from spec and other sources.

    Arguments:
        self: The current instance of the object

    Returns:
        A dictionary containing the resolved argument values
    """
    spec = self.spec
    args = self.args
    resolved_args = {}

    for arg_name, arg in args.items():
        if arg.spec or arg.value:
            continue
        else:
            if arg.default:
                resolved_args[arg_name] = arg.default
            else:
                raise ValueError(f"Cannot resolve argument {arg_name} for callable {self.fullname}: no valid value found in spec or other sources.")

    return resolved_args

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. 

    For each argument in the function signature, check if its value is provided in the spec dictionary. If it is, use that value. Otherwise, use the argument's default value or raise an error if there is no default value.

    Parameters:
        self (_AutoGrad): The AutoGrad object.

    Returns:
        A dictionary containing the resolved values for the arguments.

    Raises:
        ValueError: If an argument value cannot be resolved.
    """

    spec_defaults = {}
    for arg in self.spec.keys():
        if arg in self.args_dict:
            spec_defaults[arg] = self.args_dict[arg]
        elif arg in self.arg_defaults:
            spec_defaults[arg] = self.arg_defaults[arg]
        else:
            raise ValueError(f"{arg} not provided in spec or arguments")
    return spec_defaults

