def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required_args = []
    for option in options_spec:
        if option.get("required_when"):
            condition = option["required_when"]
            condition_met = self._check_condition(command_name, condition, args)
            if condition_met:
                required_args.append(option["arg_name"])
    return required_args

def _check_condition(self, command_name, condition, args):
    """Evaluate if condition is met based on input arguments.

    :param command_name: the command name.
    :param condition: the required_when condition.
    :param args: the received input arguments.
    :return: bool, True if condition is met, False otherwise.
    """
    if condition == "True":
        return True
    if "args" not in args:
        return False
    if "=" in condition:
        key, value = condition.split("=")
        if key in args["args"] and args["args"][key] == value:
            return True
    elif "!" in condition:
        key, value = condition.split("!")
        if key in args["args"] and args["args"][key] != value:
            return True
    return False

def _get_conditionally_required_args(self, command_name, options_spec, args):
    required_args = []
    for option in options_spec:
        if option.get('required_when') is not None:
            condition = option['required_when']
            if isinstance(condition, str):
                if condition in args:
                    required_args.append(option['name'])
            elif isinstance(condition, dict):
                condition_name = condition['name']
                if condition_name in args and args[condition_name] in condition['values']:
                    required_args.append(option['name'])
            else:
                raise ValueError('Invalid required_when condition in %s: %s' %
                                 (command_name, condition))
    return required_args

