    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down
        directly to Ansible.
    """
    if not isinstance(ir_workspace, Workspace):
        raise ValueError("ir_workspace must be an instance of Workspace")
    if not isinstance(ir_plugin, Plugin):
        raise ValueError("ir_plugin must be an instance of Plugin")
    if not isinstance(playbook_path, str):
        raise ValueError("playbook_path must be a string")
    if not isinstance(verbose, int):
        verbose = 0
    if not isinstance(extra_vars, dict):
        extra_vars = {}
    if not isinstance(ansible_args, dict):
        ansible_args = {}

    with ir_workspace.activate_plugin_env(ir_plugin):
        cmd = ["ansible-playbook", playbook_path]
