            cmd.extend(["-" + str(verbose)])
        if extra_vars:
            cmd.extend(["-e", json.dumps(extra_vars)])
        if ansible_args:
            cmd.extend(["-" + str(k) + "='" +str(v) + "'" for k, v in ansible_args.items()])
