def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    command = ["ansible-playbook"] + cli_args
    for key, value in vars_dict.items():
        command.append("-e")
        command.append("%s=%s" % (key, value))
    try:
        result = subprocess.run(command, cwd=ir_workspace.workspace_dir, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        output = result.stdout.decode("utf-8")
        error = result.stderr.decode("utf-8")
        return {"output": output, "error": error, "return_code": result.returncode}
    except subprocess.CalledProcessError as e:
        error = e.stderr.decode("utf-8")
        return {"error": error, "return_code": e.returncode}
    except OSError as e:
        return {"error": "Failed to run command: %s" % str(e), "return_code": 1}

