def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import yaml
    from collections import defaultdict

    flatten_dict = defaultdict(dict)

    plugin_spec_path = os.path.join(plugin_dir, 'plugin.yaml')
    with open(plugin_spec_path, 'r') as f:
        plugin_spec = yaml.safe_load(f)

    for prop_name, prop_spec in plugin_spec.items():
        if prop_name == 'name' or prop_name == 'version':
            continue

        if not isinstance(prop_spec, dict) or 'type' not in prop_spec:
            continue

        prop_type = prop_spec['type']
        if prop_type == 'string':
            flatten_dict[prop_name] = prop_spec.get('default', '')
        elif prop_type == 'number':
            flatten_dict[prop_name] = prop_spec.get('default', 0)
        elif prop_type == 'boolean':
            flatten_dict[prop_name] = prop_spec.get('default', False)
        else:
            continue

    return flatten_dict

